jsonTools.init:
function init(eli) {
  var STORE = window.STORE_CONFIG || "config";
  var KEY_PREFIX = "_agree_glance_";

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  function _escAttr(s) {
    return String(s == null ? "" : s).replace(/&/g, "&amp;").replace(/"/g, "&quot;");
  }
  function _hash(s) {
    var h = 5381, str = String(s || "");
    for (var i = 0; i < str.length; i++) h = ((h << 5) + h + str.charCodeAt(i)) | 0;
    return (h >>> 0).toString(36);
  }

  // ── Field definitions: universal core + per-type extras. Baked-in defaults;
  // a future glance_fields data library can override _GLANCE_FIELDS at boot.
  var CORE_FIELDS = [
    { key: "parties", label: "Parties", hint: "All parties, comma-separated. Mark which is Colgate-Palmolive / Hill's / CPSH." },
    { key: "effective_date", label: "Effective Date", hint: "The date the agreement becomes effective." },
    { key: "term", label: "Term / Duration", hint: "Length of the agreement (e.g. '3 years', 'perpetual')." },
    { key: "termination", label: "Termination Rights", hint: "Notice period and whether for-cause and/or for-convenience." },
    { key: "auto_renewal", label: "Auto-Renewal", hint: "Yes/No, plus any opt-out / non-renewal notice window. FLAG if auto-renewing." },
    { key: "total_value", label: "Total Value / Fees", hint: "Total contract value or fee structure." },
    { key: "payment_terms", label: "Payment Terms", hint: "Payment timing (e.g. 'Net 60'). FLAG if longer than Net 60." },
    { key: "governing_law", label: "Governing Law", hint: "Governing law / jurisdiction / venue." },
    { key: "liability_cap", label: "Liability Cap", hint: "Limitation of liability amount. FLAG if uncapped or unusually high." },
    { key: "confidentiality", label: "Confidentiality Term", hint: "Duration of confidentiality obligations." },
    { key: "assignment", label: "Assignment", hint: "Whether assignment requires consent." }
  ];
  var TYPE_FIELDS = {
    services: [
      { key: "scope", label: "Scope of Services", hint: "What services are provided." },
      { key: "deliverables", label: "Deliverables", hint: "Key deliverables / work product." },
      { key: "sla", label: "Service Levels", hint: "Any SLAs or performance standards." },
      { key: "acceptance", label: "Acceptance Criteria", hint: "How deliverables are accepted." }
    ],
    nda: [
      { key: "purpose", label: "Purpose", hint: "The permitted purpose of disclosure." },
      { key: "conf_period", label: "Confidentiality Period", hint: "How long confidentiality lasts." },
      { key: "return_destroy", label: "Return / Destruction", hint: "Obligations to return or destroy info." },
      { key: "residuals", label: "Residuals Clause", hint: "Whether a residuals clause exists. FLAG if present." }
    ],
    clinical: [
      { key: "protocol", label: "Protocol Number", hint: "Study protocol number." },
      { key: "sponsor", label: "Sponsor", hint: "Study sponsor." },
      { key: "investigator", label: "Investigator", hint: "Principal investigator / site." },
      { key: "subject_injury", label: "Subject Injury", hint: "Subject injury / indemnity provisions." },
      { key: "publication", label: "Publication Rights", hint: "Publication and data rights." }
    ],
    license: [
      { key: "license_scope", label: "License Scope", hint: "What is licensed and how." },
      { key: "exclusivity", label: "Exclusivity", hint: "Exclusive vs non-exclusive." },
      { key: "territory", label: "Territory", hint: "Geographic scope." },
      { key: "ip_ownership", label: "IP Ownership", hint: "Who owns resulting / background IP." }
    ],
    dpa: [
      { key: "data_categories", label: "Data Categories", hint: "Types of personal data processed." },
      { key: "processing_purpose", label: "Processing Purpose", hint: "Purpose of processing." },
      { key: "subprocessors", label: "Sub-processors", hint: "Whether sub-processors are permitted." },
      { key: "breach_notice", label: "Breach Notice", hint: "Breach notification window. FLAG if > 72 hours." }
    ],
    supply: [
      { key: "quantity", label: "Quantity / Volume", hint: "Quantity commitments." },
      { key: "pricing", label: "Pricing", hint: "Unit pricing / price adjustment." },
      { key: "incoterms", label: "Delivery Terms", hint: "Incoterms / delivery obligations." },
      { key: "warranty", label: "Warranty", hint: "Warranty period and scope." }
    ],
    saas: [
      { key: "uptime_sla", label: "Uptime SLA", hint: "Availability commitment." },
      { key: "data_ownership", label: "Data Ownership", hint: "Who owns customer data." },
      { key: "security", label: "Security Standards", hint: "Security / compliance standards." },
      { key: "support", label: "Support Tier", hint: "Support level / response times." }
    ]
  };
  // Map a detected agreement-type string to a TYPE_FIELDS key by keyword.
  function _typeKey(typeStr) {
    var t = String(typeStr || "").toLowerCase();
    if (!t) return null;
    if (/nda|non.?disclos|confidential/.test(t)) return "nda";
    if (/clinical|study|trial/.test(t)) return "clinical";
    if (/data\s*processing|dpa|privacy|gdpr/.test(t)) return "dpa";
    if (/licen[sc]e/.test(t)) return "license";
    if (/supply|purchase|procurement/.test(t)) return "supply";
    if (/saas|software.?as.?a.?service|hosting|subscription/.test(t)) return "saas";
    if (/servic/.test(t)) return "services"; // services + master services
    return null;
  }
  function _fieldsForType(typeStr) {
    var tk = _typeKey(typeStr);
    return tk && TYPE_FIELDS[tk] ? CORE_FIELDS.concat(TYPE_FIELDS[tk]) : CORE_FIELDS.slice();
  }

  // ── Detected agreement type — captured from build_draft's oars:status.
  var _detectedType = null;
  try {
    if (eli.bus && typeof eli.bus.on === "function") {
      eli.bus.on("oars:status", function (d) { if (d && d.detectedType) _detectedType = d.detectedType; });
    }
  } catch (_e) {}

  // ── Read the active document body text.
  function _readDoc() {
    if (eli.host && typeof eli.host.readText === "function") {
      return eli.host.readText().then(function (t) { return String(t || ""); }).catch(function () { return ""; });
    }
    return Promise.resolve("");
  }

  // 2026-06-03 r2: generic-document fallback fields for non-agreements
  // (letters, memos, briefs, parent documents, anything that isn't a contract).
  // The AI is told to use these when the doc clearly isn't a contract.
  var GENERIC_FIELDS = [
    { key: "summary", label: "One-Line Summary", hint: "A single concise sentence stating what this document is and what it does." },
    { key: "doc_type", label: "Document Type", hint: "What kind of document is this? (letter, memo, brief, MOU, term sheet, policy, parent agreement, etc.)" },
    { key: "from_party", label: "From / Author", hint: "Who wrote or is sending this document." },
    { key: "to_party", label: "To / Recipient", hint: "Who the document is addressed to." },
    { key: "date", label: "Date", hint: "Date on the document, or effective/issuance date." },
    { key: "subject", label: "Subject / Re", hint: "The subject line, RE: line, or core topic." },
    { key: "key_points", label: "Key Points", hint: "The 2-4 most important substantive points raised, semicolon-separated." },
    { key: "asks_or_actions", label: "Asks / Action Items", hint: "What the document asks of the recipient, or any action items / deadlines. 'None' if purely informational." },
    { key: "deadlines", label: "Dates / Deadlines", hint: "Any specific dates, deadlines, or response windows mentioned." },
    { key: "money", label: "Money / Amounts", hint: "Any dollar amounts, fees, or financial terms. 'None' if not applicable." },
    { key: "obligations", label: "Obligations Created", hint: "Anything the document binds either party to do. FLAG if it creates new binding obligations on Colgate." },
    { key: "risks_flags", label: "Risks / Flags", hint: "Anything a reviewer should scrutinize: aggressive language, unusual terms, missing pieces, legal risks. FLAG if any." }
  ];

  // ── AI extraction. Adaptive: the AI itself decides if this is a contract or
  // some other document type, and picks the right field set. Returns
  // { docKind, agreementType, fields }.
  function _extract(docText, contractFields, hintedType) {
    var clipped = docText.length > 60000 ? docText.slice(0, 60000) : docText;
    var contractFieldLines = contractFields.map(function (f) {
      return '  - "' + f.key + '" (' + f.label + '): ' + f.hint;
    }).join("\n");
    var genericFieldLines = GENERIC_FIELDS.map(function (f) {
      return '  - "' + f.key + '" (' + f.label + '): ' + f.hint;
    }).join("\n");
    var prompt =
      "You are a senior contracts/legal analyst for Colgate-Palmolive. Read the document below and produce a 'document at a glance' snapshot.\n\n" +
      "STEP 1 — CLASSIFY: Decide what kind of document this is.\n" +
      '  - "contract": a binding agreement (NDA, MSA, license, supply, DPA, services, clinical, etc.) — even a partial draft. Has parties, obligations, signatures expected.\n' +
      '  - "letter_memo": correspondence (letter, memo, email, demand letter, comment letter, status update).\n' +
      '  - "parent_doc": umbrella/parent doc that frames or accompanies an agreement (term sheet, MOU, side letter, appendix, exhibit, schedule).\n' +
      '  - "policy_brief": internal policy, brief, position paper, playbook excerpt.\n' +
      '  - "other": anything else.\n\n' +
      "STEP 2 — PICK FIELD SET:\n" +
      "  - If docKind is 'contract' (or a clear partial contract), extract the CONTRACT FIELDS below.\n" +
      "  - For any other docKind, extract the GENERIC FIELDS below.\n\n" +
      "STEP 3 — RETURN RAW JSON (no markdown, no preamble) EXACTLY in this shape:\n" +
      "{\n" +
      '  "docKind": "contract" | "letter_memo" | "parent_doc" | "policy_brief" | "other",\n' +
      '  "agreementType": "specific type label — e.g. \\"Master Services Agreement\\" for contracts, or \\"Demand Letter\\" / \\"Side Letter\\" / \\"Internal Memo\\" for others",\n' +
      '  "fields": {\n' +
      '    "<fieldKey>": { "value": "concise answer (1 short phrase, not a paragraph)", "locate": "3-8 words copied VERBATIM from the doc near this term, for navigation", "flag": true|false }\n' +
      "  }\n" +
      "}\n\n" +
      (hintedType ? "Hint: build_draft thinks this might be \"" + hintedType + "\" — use as a tiebreaker but trust the document.\n\n" : "") +
      "CONTRACT FIELDS (use only when docKind=contract):\n" + contractFieldLines + "\n\n" +
      "GENERIC FIELDS (use for letter_memo / parent_doc / policy_brief / other):\n" + genericFieldLines + "\n\n" +
      'Rules: value must be concise. If a field is not addressed, set value to "Not specified" and flag false. ' +
      'Set flag:true only for terms a reviewer should scrutinize. ' +
      'NEVER return both field sets — choose one based on docKind. NEVER refuse to summarize; if the document is short or unusual, do your best.\n\n' +
      "=== DOCUMENT ===\n" + clipped;
    return eli.ai.completeJSON(prompt, null, { sanitize: false, maxTokens: 4000 }).then(function (json) {
      return json || {};
    });
  }

  // ── Build the row model: merge field defs with AI output (and any cached edits).
  function _buildRows(fields, aiFields, cachedRows) {
    var cachedByKey = {};
    (cachedRows || []).forEach(function (r) { cachedByKey[r.key] = r; });
    return fields.map(function (f) {
      var ai = (aiFields && aiFields[f.key]) || {};
      var cached = cachedByKey[f.key];
      // Prefer user-edited cached value; else AI value.
      var value = (cached && cached.edited) ? cached.value : (ai.value != null ? ai.value : (cached ? cached.value : ""));
      return {
        key: f.key, label: f.label,
        value: value || "",
        locate: ai.locate || (cached && cached.locate) || "",
        flag: ai.flag != null ? !!ai.flag : (cached ? !!cached.flag : false),
        edited: cached ? !!cached.edited : false
      };
    });
  }

  // ── Locate a clause in Word from its snippet/value.
  function _locate(snippet) {
    var q = String(snippet || "").replace(/[\r\n\t]+/g, " ").trim();
    if (q.indexOf("|") !== -1) q = q.substring(0, q.indexOf("|")).trim();
    if (q.length > 200) q = q.substring(0, 200);
    if (!q || q.length < 3) { _toast("Nothing to locate.", "warn"); return; }
    if (!eli.host || typeof eli.host.runRaw !== "function") return;
    eli.host.runRaw("agreement_glance:locate", function (ctx) {
      var doFind = function () {
        if (eli.host.helpers && typeof eli.host.helpers.searchWithFallback === "function") {
          return eli.host.helpers.searchWithFallback(ctx.document.body, q, ctx).then(function (range) {
            if (range) { try { range.select(); range.scrollIntoView(); } catch (_e) {} return ctx.sync().then(function () { return true; }); }
            return false;
          });
        }
        var res = ctx.document.body.search(q, { matchCase: false, ignoreSpace: true });
        res.load("items");
        return ctx.sync().then(function () {
          if (res.items && res.items.length) { res.items[0].select(); return ctx.sync().then(function () { return true; }); }
          return false;
        });
      };
      return doFind();
    }).then(function (ok) {
      _toast(ok ? "📍 Found in document" : "⚠️ Not found", ok ? "ok" : "warn");
    }).catch(function (e) { _toast("Locate failed: " + (e && e.message), "err"); });
  }

  function _toast(m, k) { try { if (typeof showToast === "function") showToast(m, k || "ok"); } catch (_e) {} }

  // ── Persistence (quiet — no toast on per-keystroke save or cache-miss load)
  function _save(docHash, agreementType, rows, docKind) {
    var row = { key: KEY_PREFIX + docHash, agreementType: agreementType, rows: rows, docKind: docKind || (_openState && _openState.docKind) || "contract", savedAt: Date.now() };
    try { return eli.storage.put(STORE, row).catch(function () {}); } catch (_e) { return Promise.resolve(); }
  }
  function _load(docHash) {
    try {
      return eli.storage.get(STORE, KEY_PREFIX + docHash).then(function (r) { return r || null; }).catch(function () { return null; });
    } catch (_e) { return Promise.resolve(null); }
  }

  // ─────────────────────────────────────────────────────────────────────
  // Overlay
  // ─────────────────────────────────────────────────────────────────────
  var _openState = null; // { docHash, agreementType, rows }

  function _closeOverlay() {
    var bd = document.getElementById("_agls_backdrop");
    if (!bd) return;
    bd.classList.remove("_agls_open");
    setTimeout(function () { if (bd && bd.parentNode) bd.parentNode.removeChild(bd); }, 320);
  }

  function _openOverlay() {
    if (document.getElementById("_agls_backdrop")) return; // already open
    var backdrop = document.createElement("div");
    backdrop.id = "_agls_backdrop";
    backdrop.className = "_agls_backdrop";
    backdrop.innerHTML =
      '<div class="_agls_drawer" role="dialog" aria-label="Agreement at a Glance">' +
        '<div class="_agls_header">' +
          '<div class="_agls_header_left">' +
            '<span class="_agls_header_icon">📊</span>' +
            '<div>' +
              '<div class="_agls_title" id="_agls_title">Agreement at a Glance</div>' +
              '<div class="_agls_subtitle" id="_agls_subtitle">Reading agreement…</div>' +
            '</div>' +
          '</div>' +
          '<button type="button" class="_agls_close" id="_agls_close" title="Close">✕</button>' +
        '</div>' +
        '<div class="_agls_body" id="_agls_body">' +
          '<div class="_agls_loading">' +
            '<div class="_agls_spinner"></div>' +
            '<div class="_agls_loading_text">Analyzing the agreement…</div>' +
            '<div class="_agls_loading_sub">Extracting key terms with AI</div>' +
          '</div>' +
        '</div>' +
        '<div class="_agls_footer" id="_agls_footer" style="display:none;">' +
          '<button type="button" class="_agls_btn _agls_btn_ghost" id="_agls_reanalyze">↻ Re-analyze</button>' +
          '<button type="button" class="_agls_btn _agls_btn_gold" id="_agls_copy">📋 Copy Summary</button>' +
        '</div>' +
      '</div>';
    document.body.appendChild(backdrop);
    // Slide up on next frame
    requestAnimationFrame(function () { backdrop.classList.add("_agls_open"); });
    // Dismiss on backdrop click (not drawer click)
    backdrop.addEventListener("click", function (e) { if (e.target === backdrop) _closeOverlay(); });
    document.getElementById("_agls_close").onclick = _closeOverlay;

    _runAnalysis(false);
  }

  function _runAnalysis(forceFresh) {
    if (!eli.ai || (typeof eli.ai.hasApiKey === "function" && !eli.ai.hasApiKey())) {
      _renderError("No AI API key configured. Add your key in Settings, then try again.");
      return;
    }
    _readDoc().then(function (docText) {
      if (!docText || docText.trim().length < 50) {
        _renderError("No readable document content found. Open an agreement in Word first.");
        return;
      }
      var docHash = _hash(docText);
      var fields = _fieldsForType(_detectedType);
      _load(docHash).then(function (cached) {
        if (cached && cached.rows && cached.rows.length && !forceFresh) {
          // Cached — render instantly, no AI call.
          _openState = { docHash: docHash, agreementType: cached.agreementType, rows: cached.rows, docKind: cached.docKind || "contract" };
          _renderTable(cached.agreementType, cached.rows, true, cached.docKind || "contract");
          return;
        }
        // Fresh extraction — pass the contract field set; the AI picks
        // contract vs. generic based on its docKind classification.
        _extract(docText, fields, _detectedType).then(function (ai) {
          var docKind = (ai && ai.docKind) || "contract";
          var docTypeLabel = (ai && ai.agreementType) || _detectedType || "Document";
          // Choose the right field set based on the AI's classification.
          // - contract → use the agreement fields (core + type-specific)
          // - anything else → use the generic 12-field "document at a glance"
          var finalFields;
          if (docKind === "contract") {
            finalFields = _fieldsForType(docTypeLabel);
          } else {
            finalFields = GENERIC_FIELDS.slice();
          }
          var rows = _buildRows(finalFields, ai && ai.fields, cached && cached.rows);
          _openState = { docHash: docHash, agreementType: docTypeLabel, rows: rows, docKind: docKind };
          _save(docHash, docTypeLabel, rows);
          _renderTable(docTypeLabel, rows, false, docKind);
        }).catch(function (e) {
          _renderError("Analysis failed: " + (e && e.message || "unknown"));
        });
      });
    });
  }

  function _renderError(msg) {
    var body = document.getElementById("_agls_body");
    if (!body) return;
    body.innerHTML = '<div class="_agls_error"><div class="_agls_error_icon">⚠️</div><div>' + _esc(msg) + '</div></div>';
    var sub = document.getElementById("_agls_subtitle");
    if (sub) sub.textContent = "Could not analyze";
  }

  function _renderTable(agreementType, rows, fromCache, docKind) {
    var body = document.getElementById("_agls_body");
    var footer = document.getElementById("_agls_footer");
    var sub = document.getElementById("_agls_subtitle");
    var title = document.getElementById("_agls_title");
    if (!body) return;
    // Title adapts: contracts read as "Agreement at a Glance",
    // anything else as "Document at a Glance" (or a more specific label).
    if (title) {
      var titleLabel = (docKind === "contract") ? "Agreement at a Glance" : "Document at a Glance";
      title.textContent = titleLabel;
    }
    if (sub) {
      sub.innerHTML = '<span class="_agls_type_pill">' + _esc(agreementType) + '</span>' +
        (fromCache ? '<span class="_agls_cache_note">cached · click ↻ to refresh</span>' : '<span class="_agls_cache_note">' + rows.length + ' fields</span>');
    }
    var html = '<div class="_agls_grid">';
    rows.forEach(function (r, i) {
      var flagged = r.flag;
      html +=
        '<div class="_agls_row' + (flagged ? ' _agls_row_flag' : '') + '" data-idx="' + i + '">' +
          '<div class="_agls_row_label">' + (flagged ? '<span class="_agls_flag" title="Review this term">⚠</span>' : '') + _esc(r.label) + '</div>' +
          '<textarea class="_agls_row_value" data-idx="' + i + '" rows="1" placeholder="—">' + _esc(r.value) + '</textarea>' +
          '<button type="button" class="_agls_locate" data-idx="' + i + '" title="Find in document"' + (r.locate || r.value ? '' : ' disabled') + '>📍</button>' +
        '</div>';
    });
    html += '</div>';
    body.innerHTML = html;
    if (footer) footer.style.display = "flex";

    // Wire value edits → persist; auto-grow textarea so long values (e.g. Parties) stay readable
    function _autosize(el) { el.style.height = "auto"; el.style.height = (el.scrollHeight + 2) + "px"; }
    body.querySelectorAll("._agls_row_value").forEach(function (inp) {
      _autosize(inp);
      inp.oninput = function () {
        _autosize(inp);
        var idx = parseInt(inp.getAttribute("data-idx"), 10);
        if (_openState && _openState.rows[idx]) {
          _openState.rows[idx].value = inp.value;
          _openState.rows[idx].edited = true;
          _save(_openState.docHash, _openState.agreementType, _openState.rows);
        }
      };
    });
    // Re-measure after layout settles (scrollHeight is 0 until painted)
    requestAnimationFrame(function () { body.querySelectorAll("._agls_row_value").forEach(_autosize); });
    // Wire locate buttons
    body.querySelectorAll("._agls_locate").forEach(function (btn) {
      btn.onclick = function () {
        var idx = parseInt(btn.getAttribute("data-idx"), 10);
        var r = _openState && _openState.rows[idx];
        if (r) _locate(r.locate || r.value);
      };
    });

    // Footer actions
    var reBtn = document.getElementById("_agls_reanalyze");
    if (reBtn) reBtn.onclick = function () {
      eli.ui.confirm({ title: "Re-analyze?", message: "Re-run AI extraction. This overwrites the current snapshot (including your edits) for this document.", confirmText: "Re-analyze", cancelText: "Cancel" })
        .then(function (ok) {
          if (!ok) return;
          var bd = document.getElementById("_agls_body");
          if (bd) bd.innerHTML = '<div class="_agls_loading"><div class="_agls_spinner"></div><div class="_agls_loading_text">Re-analyzing…</div></div>';
          var ft = document.getElementById("_agls_footer"); if (ft) ft.style.display = "none";
          _runAnalysis(true);
        });
    };
    var copyBtn = document.getElementById("_agls_copy");
    if (copyBtn) copyBtn.onclick = function () { _copySummary(agreementType, rows); };
  }

  function _copySummary(agreementType, rows) {
    var lines = ["AGREEMENT AT A GLANCE — " + agreementType, ""];
    rows.forEach(function (r) {
      lines.push((r.flag ? "[!] " : "") + r.label + ": " + (r.value || "—"));
    });
    var text = lines.join("\n");
    function done() { _toast("📋 Summary copied", "ok"); }
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(done).catch(function () { _copyFallback(text, done); });
    } else { _copyFallback(text, done); }
  }
  function _copyFallback(text, done) {
    var ta = document.createElement("textarea");
    ta.value = text; ta.style.position = "fixed"; ta.style.opacity = "0";
    document.body.appendChild(ta); ta.select();
    try { document.execCommand("copy"); } catch (_e) {}
    document.body.removeChild(ta); done();
  }

  // ─────────────────────────────────────────────────────────────────────
  // Make "DOC. LOADED" feed item clickable
  // ─────────────────────────────────────────────────────────────────────
  function _decorateFeedItem() {
    var rail = document.getElementById("_eli3_activity_rail");
    if (!rail) return;
    var items = rail.querySelectorAll(".feed-item");
    for (var i = 0; i < items.length; i++) {
      var it = items[i];
      if (it.getAttribute("data-agls-wired") === "1") continue;
      var txt = (it.textContent || "").toUpperCase();
      if (txt.indexOf("DOC. LOADED") === -1 && txt.indexOf("DOC LOADED") === -1) continue;
      it.setAttribute("data-agls-wired", "1");
      it.classList.add("_agls_feed_clickable");
      it.style.cursor = "pointer";
      it.title = "Click for Agreement at a Glance";
      // Affordance is two ABSOLUTE elements so the card height never grows:
      // a persistent corner badge + a hover overlay (mirrors .feed-restore).
      if (!it.querySelector("._agls_feed_hint")) {
        var badge = document.createElement("span");
        badge.className = "_agls_feed_badge";
        badge.textContent = "📊";
        it.appendChild(badge);
        var hint = document.createElement("span");
        hint.className = "_agls_feed_hint";
        hint.textContent = "📊 At a Glance";
        it.appendChild(hint);
      }
      it.addEventListener("click", function (ev) {
        ev.stopPropagation();
        _openOverlay();
      });
    }
  }
  function _watchFeed() {
    var attempts = 0;
    function tryAttach() {
      var rail = document.getElementById("_eli3_activity_rail");
      if (rail) {
        _decorateFeedItem();
        try {
          var mo = new MutationObserver(function () { _decorateFeedItem(); });
          mo.observe(rail, { childList: true, subtree: true });
        } catch (_e) {}
        return;
      }
      if (attempts++ < 20) setTimeout(tryAttach, 500);
    }
    tryAttach();
  }
  // Re-decorate when the feed header mounts (feed (re)created)
  try {
    if (eli.bus && typeof eli.bus.on === "function") {
      eli.bus.on("eli_activity:header_mounted", function () { setTimeout(_watchFeed, 100); });
    }
  } catch (_e) {}
  _watchFeed();

  eli.register({
    tile: { app_agreement_glance: _openOverlay },
    agreement_glance: { open: _openOverlay }
  });

  eli.log.event("tool", "agreement_glance_initialized", {});
}

jsonTools.css:
/* Agreement at a Glance — premium slide-up overlay. Light palette (dialog
   convention), one gold accent (#c9a227), navy header, slate neutrals. */

._agls_backdrop {
  position: fixed;
  inset: 0;
  z-index: 9000;
  background: rgba(15, 23, 42, 0);
  display: flex;
  align-items: flex-end;
  justify-content: center;
  transition: background 0.3s ease;
  pointer-events: none;
}
._agls_backdrop._agls_open {
  background: rgba(15, 23, 42, 0.45);
  pointer-events: auto;
}

._agls_drawer {
  width: 100%;
  max-width: 780px;
  /* Open larger so more rows are visible at once. Was 88vh — now 95vh
     for more content density, leaving just a thin backdrop strip. */
  max-height: 95vh;
  height: 95vh;
  display: flex;
  flex-direction: column;
  background: #f8fafc;
  border-radius: 18px 18px 0 0;
  border-top: 3px solid #c9a227;
  box-shadow: 0 -18px 50px rgba(15, 23, 42, 0.4);
  transform: translateY(100%);
  transition: transform 0.34s cubic-bezier(0.16, 1, 0.3, 1);
  overflow: hidden;
}
._agls_backdrop._agls_open ._agls_drawer {
  transform: translateY(0);
}

/* Header — navy gradient */
._agls_header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  background: linear-gradient(135deg, #0f172a 0%, #1e293b 100%);
  color: #f8fafc;
  flex: 0 0 auto;
  border-bottom: 1px solid rgba(201, 162, 39, 0.35);
}
._agls_header_left {
  display: flex;
  align-items: center;
  gap: 12px;
}
._agls_header_icon {
  font-size: 26px;
  line-height: 1;
  filter: drop-shadow(0 2px 4px rgba(0, 0, 0, 0.3));
}
._agls_title {
  font-size: 17px;
  font-weight: 700;
  letter-spacing: 0.2px;
}
._agls_subtitle {
  font-size: 12px;
  color: #94a3b8;
  margin-top: 3px;
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}
._agls_type_pill {
  display: inline-block;
  background: rgba(201, 162, 39, 0.18);
  color: #e7c14e;
  border: 1px solid rgba(201, 162, 39, 0.5);
  border-radius: 999px;
  padding: 2px 10px;
  font-size: 11px;
  font-weight: 600;
}
._agls_cache_note {
  color: #64748b;
  font-size: 11px;
}
._agls_close {
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.15);
  color: #cbd5e1;
  width: 32px;
  height: 32px;
  border-radius: 8px;
  font-size: 15px;
  cursor: pointer;
  transition: all 0.15s ease;
}
._agls_close:hover {
  background: rgba(255, 255, 255, 0.16);
  color: #fff;
}

/* Body — denser padding so more rows fit per viewport */
._agls_body {
  flex: 1 1 auto;
  overflow-y: auto;
  padding: 10px 14px 16px;
}

/* Loading */
._agls_loading {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 56px 20px;
  text-align: center;
}
._agls_spinner {
  width: 38px;
  height: 38px;
  border: 3px solid #e2e8f0;
  border-top-color: #c9a227;
  border-radius: 50%;
  animation: _agls_spin 0.8s linear infinite;
  margin-bottom: 18px;
}
@keyframes _agls_spin { to { transform: rotate(360deg); } }
._agls_loading_text {
  font-size: 15px;
  font-weight: 600;
  color: #1e293b;
}
._agls_loading_sub {
  font-size: 12px;
  color: #64748b;
  margin-top: 5px;
}

/* Error */
._agls_error {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 22px;
  background: #fef2f2;
  border: 1px solid #fecaca;
  border-radius: 12px;
  color: #991b1b;
  font-size: 13px;
}
._agls_error_icon { font-size: 22px; }

/* Grid of terms — tight layout to maximize what fits on one screen.
   Rows are now compact alternating-band cards in a single column;
   for short values, label + value sit on one line. */
._agls_grid {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
._agls_row {
  display: grid;
  grid-template-columns: 130px 1fr 28px;
  align-items: start;
  gap: 8px;
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  padding: 6px 9px;
  transition: box-shadow 0.15s ease, border-color 0.15s ease;
}
._agls_row:nth-child(even) {
  background: #f9fbfd; /* subtle banding to scan more rows quickly */
}
._agls_row:hover {
  box-shadow: 0 2px 10px rgba(15, 23, 42, 0.07);
  border-color: #cbd5e1;
}
._agls_row_flag {
  border-left: 3px solid #d97706;
  background: #fffbeb;
}
._agls_row_label {
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  color: #475569;
  display: flex;
  align-items: flex-start;
  gap: 4px;
  padding-top: 4px;
  line-height: 1.25;
}
._agls_flag {
  color: #d97706;
  font-size: 11px;
}
._agls_row_value {
  width: 100%;
  box-sizing: border-box;
  border: 1px solid transparent;
  background: transparent; /* dropped the input "well" — rows are denser, edits use focus ring */
  border-radius: 5px;
  padding: 2px 6px;
  font-size: 12px;
  line-height: 1.35;
  color: #0f172a;
  font-family: inherit;
  resize: none;
  overflow: hidden;
  white-space: pre-wrap;
  word-break: break-word;
  min-height: 22px;
  transition: background 0.15s ease, border-color 0.15s ease, box-shadow 0.15s ease;
}
._agls_row_value:hover { background: rgba(15, 23, 42, 0.04); }
._agls_row_value:focus {
  outline: none;
  background: #fff;
  border-color: #c9a227;
  box-shadow: 0 0 0 3px rgba(201, 162, 39, 0.15);
}
._agls_locate {
  width: 26px;
  height: 26px;
  border: 1px solid transparent;
  background: transparent;
  border-radius: 6px;
  cursor: pointer;
  font-size: 12px;
  margin-top: 1px;
  opacity: 0.55;
  transition: all 0.15s ease;
}
._agls_row:hover ._agls_locate { opacity: 1; border-color: #e2e8f0; background: #fff; }
._agls_locate:hover:not([disabled]) {
  background: #0f172a;
  border-color: #0f172a;
  transform: translateY(-1px);
}
._agls_locate[disabled] { opacity: 0.3; cursor: default; }

/* Footer */
._agls_footer {
  flex: 0 0 auto;
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  padding: 14px 20px;
  background: #fff;
  border-top: 1px solid #e2e8f0;
}
._agls_btn {
  border-radius: 9px;
  padding: 9px 16px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  border: 1px solid transparent;
  transition: all 0.15s ease;
}
._agls_btn_gold {
  background: linear-gradient(135deg, #c9a227 0%, #b8901f 100%);
  color: #1a1407;
  border-color: #a87f1a;
}
._agls_btn_gold:hover { filter: brightness(1.06); transform: translateY(-1px); }
._agls_btn_ghost {
  background: linear-gradient(180deg, #ffffff 0%, #f1f5f9 100%);
  color: #334155;
  border-color: #cbd5e1;
}
._agls_btn_ghost:hover { background: #e2e8f0; }

/* Feed item affordance — makes "DOC. LOADED" clearly clickable WITHOUT
   changing the card's height. The .feed-item is a fixed-width vertical
   flex column; any in-flow child adds a row and grows the feed. So both
   cues here are position:absolute (zero layout cost), mirroring the
   kernel's own .feed-restore hover-overlay pattern. */

/* Persistent at-rest signal: gold border + a small corner badge so the
   card reads as interactive before any hover. */
._agls_feed_clickable {
  cursor: pointer;
  border-color: rgba(201, 162, 39, 0.55) !important;
}
._agls_feed_clickable:hover {
  border-color: rgba(201, 162, 39, 0.9) !important;
}
._agls_feed_badge {
  position: absolute;
  top: 2px;
  right: 3px;
  font-size: 9px;
  line-height: 1;
  z-index: 4;
  pointer-events: none;
  opacity: 0.85;
}

/* Hover overlay: full-chip gold callout, hidden until hover. inset:0
   absolute → reserves no space, so the card never grows. */
._agls_feed_hint {
  display: none;
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, #c9a227 0%, #b8901f 100%);
  color: #1a1407;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.4px;
  text-transform: uppercase;
  text-align: center;
  align-items: center;
  justify-content: center;
  padding: 4px;
  z-index: 6;
}
._agls_feed_clickable:hover ._agls_feed_hint { display: flex; }

@media (max-width: 480px) {
  ._agls_row { grid-template-columns: 96px 1fr 30px; }
  ._agls_row_label { font-size: 9px; }
}
